  `live_room_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `student_completed_at` datetime NULL DEFAULT NULL,
  `tutor_completed_at` datetime NULL DEFAULT NULL,
