  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `schedule_type` enum('SINGLE','LONG_TERM') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SINGLE',
