INSERT INTO `news` VALUES (1, 'Hướng dẫn ôn thi tốt nghiệp THPT đạt kết quả cao', 'Tổng hợp kinh nghiệm và phương pháp ôn tập hiệu quả từ các gia sư thủ khoa trong kỳ thi tốt nghiệp THPT.', 'Các chuyên đề ôn luyện trọng tâm, cấu trúc đề thi chính thức và các mẹo làm bài điểm cao được biên soạn bởi đội ngũ gia sư KNTech.', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=150', 'Toán', '2026-06-18 02:14:28');
INSERT INTO `news` VALUES (2, 'Phương pháp học kèm trực tuyến hiệu quả cùng gia sư', 'Cách tận dụng bảng vẽ điện tử và trao đổi trực tiếp trong lớp học ảo để tối ưu hóa kết quả học tập của con.', 'Học trực tuyến 1-1 giúp gia sư theo sát học sinh, giải đáp thắc mắc kịp thời và thiết lập lộ trình học tập cá nhân hóa cho từng con.', 'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=150', 'Lý', '2026-06-18 02:14:28');
INSERT INTO `news` VALUES (3, 'Kế hoạch tự ôn tập môn Hóa học đạt điểm 9+ trong 30 ngày', 'Chia sẻ cẩm nang ôn tập từ mất gốc đến nâng cao, hướng dẫn học các chuyên đề trọng điểm đạt kết quả tốt nhất.', 'Các bài giảng trực tuyến tổng ôn bài tập lý thuyết Hóa học hữu cơ và vô cơ được biên soạn độc quyền.', 'https://images.unsplash.com/photo-1532187643603-ba119ca4109e?w=150', 'Hóa', '2026-06-18 02:14:28');
